package demo; import com.mojang.blaze3d.vertex.PoseStack; import com.mojang.math.Axis; public class Probe { static String row(PoseStack s){var m=s.last().pose();return Float.toString(m.m00())+","+Float.toString(m.m11())+","+Float.toString(m.m22())+","+Float.toString(m.m30())+","+Float.toString(m.m31())+","+Float.toString(m.m32());} public static String run(){PoseStack s=new PoseStack();String a="identity="+row(s);s.pushPose();s.translate(1.25f,-2.5f,3.75f);s.scale(-2f,3f,4f);String b="nested="+row(s);s.popPose();String e;try{s.popPose();e="empty=none";}catch(Exception x){e="empty="+x.getClass().getName();}return a+"\n"+b+"\n"+e;} }
